import{_ as t,I as e,c as n,o,j as i,ap as s,a,J as g}from"./chunks/framework.BVMg0REN.js";const k=JSON.parse('{"title":"常驻任务","description":"","frontmatter":{},"headers":[],"relativePath":"Activity/Permanent.md","filePath":"zh/Activity/Permanent.md","lastUpdated":1784686420000}'),h={name:"Activity/Permanent.md"},u={id:"常驻任务",tabindex:"-1"};function d(c,l,m,b,p,f){const r=e("Badge");return o(),n("div",null,[i("h1",u,[l[0]||(l[0]=a("常驻任务")),g(r,{type:"warning",text:"任务"}),l[1]||(l[1]=a()),l[2]||(l[2]=i("a",{class:"header-anchor",href:"#常驻任务","aria-label":"Permalink to “常驻任务”"},"​",-1))]),l[3]||(l[3]=s('<div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>大部分任务可点击任务名称右侧的齿轮⚙️，进行具体设置以适配不同需求。 部分任务配置了图文或视频版，请自行前往<a href="https://space.bilibili.com/3690998968355771" target="_blank" rel="noreferrer">B站</a>或<a href="https://www.xiaohongshu.com/user/profile/685e3301000000001b0229ed" target="_blank" rel="noreferrer">小红书</a>查阅</p></div><h2 id="启动-关闭游戏" tabindex="-1">启动/关闭游戏 <a class="header-anchor" href="#启动-关闭游戏" aria-label="Permalink to “启动/关闭游戏”">​</a></h2><ul><li><strong>启动<code>biubiu</code>加速器</strong>：需要保证想要加速的代号鸢对应区服在首页第一个的位置，否则可能会加速错误。</li><li><strong>启动游戏</strong>：点击开始任务旁的齿轮，选择服务器 <ul><li>如鸢官服/TAP服/九游服等，代号鸢港服/台服（需切换繁中）。</li><li><strong>该任务启动前确保游戏未运行</strong>，否则会卡住。</li><li>若习惯先开游戏再启<code>MaaYuan</code>，请勿勾选此任务。</li><li>无法启动此任务请查阅<a href="https://maayuan.top/FAQ/01-general-issues.html" target="_blank" rel="noreferrer">常见问题</a>。</li></ul></li><li><strong>关闭游戏</strong>：直接关闭游戏端。</li></ul><h2 id="鸢报" tabindex="-1">鸢报 <a class="header-anchor" href="#鸢报" aria-label="Permalink to “鸢报”">​</a></h2><ul><li><strong>鸢报四连-日常专用</strong>：这是日常一条龙专用的单次版自动做鸢报，只能在四种鸢报的次数都充足时顺利进行。</li><li><strong>小道消息-日常专用</strong>：这是用来衔接日常一条龙专用的单次版自动做小道消息。</li><li><strong>鸢报四合一</strong>：可循环执行，轮流做激活的鸢报事件，不浪费时间。 <ul><li>会自动跳过鸟食数量不足的事件。</li><li>为了循环检查，决策事件和没有建材箱的物资支援会强制做掉。</li><li>如不想“浪费”鸡炙，请使用单独的待办公务任务。</li></ul></li><li><strong>待办公务</strong>：循环任务，可选具体内容，如是否做物资支援/决策事件/战斗。</li></ul><h2 id="故事" tabindex="-1">故事 <a class="header-anchor" href="#故事" aria-label="Permalink to “故事”">​</a></h2><ul><li><strong>6-24/7-15刷到体力耗尽</strong>： <ul><li>不会消耗白金币购买体力。</li><li>极速版正在绝赞测试中，如遇到问题请增加动作延时，或先切换回原版，欢迎反馈。</li><li>队伍1、2、3是指选编队时从左到右的顺序，与队伍名无关，也不用改队伍名字。</li></ul></li><li><strong>6-24/7-15指定循环次数</strong>：这是可以指定循环次数的版本。</li></ul><h2 id="心纸营建" tabindex="-1">心纸营建 <a class="header-anchor" href="#心纸营建" aria-label="Permalink to “心纸营建”">​</a></h2><ul><li><strong>心纸营建</strong>：单次执行版，自动派遣（适合佛脚刷分或密探不足玩家）。 <ul><li>可选线路材料/难度1-5/派遣次数1-4/是否打造家具。</li></ul></li><li><strong>家具历险首通</strong>：可循环执行。 <ul><li>首通或刷佛脚使用，建议手动选好密探+在历险内配过一次队后再使用本任务。</li><li>也可以自动跑到战斗处再停止任务、进行编队，编好队后再次开始任务。</li><li>支持从活动界面/选择历险路线界面/历险关卡内开始任务，会根据选项自动接管。</li></ul></li><li><strong>自动刷神秘洞窟</strong>：循环任务，可选游戏内置自动战斗/抄作业，可指定队伍，抄作业请看<a href="https://share.maayuan.top/" target="_blank" rel="noreferrer">作业站</a>，在家具历险两个洞窟处开始任务。</li></ul><h2 id="历练" tabindex="-1">历练 <a class="header-anchor" href="#历练" aria-label="Permalink to “历练”">​</a></h2><ul><li><strong>铜钱历练</strong>：日常任务，可选历练级别/次数。</li><li><strong>经验历练</strong>：日常任务，可选历练级别/次数。</li><li><strong>修为历练</strong>：日常任务，可选历练类别/级别/次数。</li></ul><h2 id="据点" tabindex="-1">据点 <a class="header-anchor" href="#据点" aria-label="Permalink to “据点”">​</a></h2><ul><li><strong>据点日常</strong>：日常任务。 <ul><li>强制派遣是指即使当前派遣未结束，也会召回并重新派遣，保证每天能定时无脑拉满3次派遣。</li><li>不要和普通的派遣同时勾选。</li></ul></li><li><strong>据点商人购物</strong>：日常任务，自动购买并免费刷新1次，多商品需添加多个任务。</li><li><strong>派遣四合一</strong>：循环任务。 <ul><li>各据点的派遣阵容皆可自定义，具体方法见文件夹里的自定义派遣脚本修改说明.md（用记事本可以打开）。</li><li>强制派遣同上。</li></ul></li><li><strong>据点情报二合一</strong>：循环任务，不管有没有月卡，还没做过的情报都会通过自动走格子完成。</li></ul><h2 id="兰台" tabindex="-1">兰台 <a class="header-anchor" href="#兰台" aria-label="Permalink to “兰台”">​</a></h2><ul><li><strong>白鹄扫荡</strong>：日常任务，仅扫荡。</li><li><strong>自动爬兰台</strong>：循环任务。 <ul><li>暂只支持简中。自动导航已加载，理论上可在任意界面开始任务。</li><li>理论上打完30后会自动选恋念/领奖励然后继续刷下一难度，当期全打完会自动检查其他期并选择未通关的其他期继续爬。</li><li>体力不足时和战斗失败时都会停止任务。</li></ul></li></ul><h2 id="地宫" tabindex="-1">地宫 <a class="header-anchor" href="#地宫" aria-label="Permalink to “地宫”">​</a></h2><ul><li><p><strong>地宫助手</strong>：循环任务，目前为试用版，欢迎反馈。</p><ul><li>支持自动爬塔，优先打未通关关卡，全通后则默认扫荡，默认会把10次都扫掉，次数不足时自动停止</li><li>爬塔默认当前队伍战斗，遇禁用属性（火阴/水阳/地风）自动切备用队，需提前配队。</li><li>自动雀部解密，仅在开启自动领地宫奖励时，在任务列表中识别到该任务未做完时才执行，会继续开默认（上一次）开过的筒子。</li><li>默认扫10次，不足自动停；自动解密（需开启领奖任务且未完成时）。</li></ul></li></ul><h2 id="观星" tabindex="-1">观星 <a class="header-anchor" href="#观星" aria-label="Permalink to “观星”">​</a></h2><ul><li>选择星图（当季/古老/深空）和观星方式（多达六种方式，总有一款适合你） <ul><li><strong>【需月卡】一键观星</strong>：会观30x2次，以便直接完成消耗20w五铢钱的日常</li></ul></li></ul><h2 id="活动" tabindex="-1">活动 <a class="header-anchor" href="#活动" aria-label="Permalink to “活动”">​</a></h2><ul><li><strong>每日进膳</strong>：自动领取陈登的小点心。</li><li><strong>初见日</strong>： <ul><li>使用前确保新手指引环节已完成（所有地点已解锁）。可选是否自动领取奖励。</li><li>单一物品模式：不需要agent。物品使用优先级为绿&gt;蓝&gt;紫&gt;金，默认摆满，不足会自动购买。</li><li>多项物品模式：需要agent才能运行，默认摆前4个物品，不足4个会自动购买。</li></ul></li><li><strong>楼主查岗</strong>： <ul><li>自动领取楼主查岗奖励，</li><li>可选是否自动购买天机符传x1（需提前解锁二级密码）以及是否领取100体力。</li></ul></li><li><strong>日常收尾</strong>：相见/家具互动、首位密探升级、每日分享、密探送礼（1或3次）、第三次小道消息、收取密探特训奖励。</li></ul><h2 id="其他功能" tabindex="-1">其他功能 <a class="header-anchor" href="#其他功能" aria-label="Permalink to “其他功能”">​</a></h2><ul><li><strong>领月卡福利</strong>：领取月卡&amp;商店免费20体力（可选都领或仅领商店）。</li><li><strong>红点消除助手</strong>：自动处理心纸居读信、密探传闻等。</li><li><strong>百宝箱</strong>：随缘增加各种解手操作。</li><li><strong>三千世界刷成就</strong>：在宇宙匣-三千世界内想刷的关卡内（页面下方有“体验”按钮）开始任务。</li><li><strong>自动抄作业V3</strong>：需要在战斗中展开手动/自动/倍速的面板。 <ul><li>如使用<code>MaaYuan</code>左侧边栏中的抄作业专用面板进行战斗，需要在任务列表内保留“自动抄作业V3”任务。</li><li>详细操作请参阅<a href="https://share.maayuan.top/" target="_blank" rel="noreferrer">作业站</a>及<a href="https://maayuan.top/Features/AutoBattle.html" target="_blank" rel="noreferrer">自动战斗说明</a>。</li></ul></li></ul>',23))])}const P=t(h,[["render",d]]);export{k as __pageData,P as default};
